const markdown = process.env.MARKDOWN;
if (typeof markdown !== 'string' || markdown.length === 0) {
  throw new Error('markdown input is required and must be a non-empty string');
}
globalThis.markdown = markdown;

const { fromMarkdown } = await import('mdast-util-from-markdown');
const { toMarkdown } = await import('mdast-util-to-markdown');
const { gfmTaskListItem } = await import('micromark-extension-gfm-task-list-item');
const { gfmTaskListItemFromMarkdown, gfmTaskListItemToMarkdown } = await import('mdast-util-gfm-task-list-item');

const tree = fromMarkdown(globalThis.markdown, {
  extensions: [gfmTaskListItem],
  mdastExtensions: [gfmTaskListItemFromMarkdown]
});

const result = toMarkdown(tree, {
  extensions: [gfmTaskListItemToMarkdown]
});

globalThis.result = result;

if (typeof globalThis.result !== 'string') {
  throw new Error('result is not a string');
}
console.log(JSON.stringify({ markdown: globalThis.result }));
